def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]
    last_me = my_moves[-1]
    last_opp = opp_moves[-1]

    opp_d = opp_moves.count('D')
    opp_c = n - opp_d

    if opp_d > n * 0.6:
        return 'D'

    if last_me == 'C' and last_opp == 'D':
        cd_streak = 0
        for i in range(n - 1, -1, -1):
            if my_moves[i] == 'C' and opp_moves[i] == 'D':
                cd_streak += 1
            else:
                break
        if opp_d <= n * 0.3:
            if cd_streak < 5:
                return 'C'
        else:
            if cd_streak < 2:
                return 'C'
        return 'D'

    if last_me == 'D' and last_opp == 'D':
        if opp_c > n * 0.5:
            dd_streak = 0
            for i in range(n - 1, -1, -1):
                if my_moves[i] == 'D' and opp_moves[i] == 'D':
                    dd_streak += 1
                else:
                    break
            if dd_streak >= 2:
                if rng.random() < 0.7:
                    return 'C'
        return 'D'

    if last_me == 'D' and last_opp == 'C':
        return 'C'

    if last_me == 'C' and last_opp == 'C':
        return 'C'

    return 'C'
